import{d as h,C as a,o as g,c,j as n,a as l,E as i,a3 as t}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"说卦传","description":"讲八卦作法、卦德、取象与方位的传——从三才六画到先后天秩序，建立理解卦象语言的入口。","frontmatter":{"title":"说卦传","description":"讲八卦作法、卦德、取象与方位的传——从三才六画到先后天秩序，建立理解卦象语言的入口。","category":"guide","aliases":["说卦传","说卦","shuo gua zhuan"],"source":["《周易·说卦传》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/shi-yi/shuo-gua-zhuan.md","filePath":"yijing/shi-yi/shuo-gua-zhuan.md","lastUpdated":1790587309000}'),b={name:"yijing/shi-yi/shuo-gua-zhuan.md"},q=h({...b,setup(m){const o=[{id:"duan-01",label:"一、圣人作易",showLabel:!0,sentences:[["昔者圣人之作《易》也，",{text:"幽赞",glossary:"g01"},"于神明而生蓍，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻，和顺于道德而理于义，穷理尽性以至于命。"]],note:["从前圣人作《易》，暗中借助神明而创出蓍草占筮，参合天地之数而立数，观察阴阳之变而立卦，发挥刚柔而生爻，进而合于道德、条理于义，穷究事理、尽己之性，直至通达于命。"]},{id:"duan-02",label:"二、顺性命之理",showLabel:!0,sentences:[["昔者圣人之作《易》也，将以顺性命之理。是以立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。"]],note:["圣人作《易》，是为了顺性命之理：所以立天之道叫做阴与阳，立地之道叫做柔与刚，立人之道叫做仁与义。"]},{id:"duan-03",label:"三、三才六画",showLabel:!0,sentences:[["兼",{text:"三才",glossary:"g02"},"而两之，故《易》六画而成卦。分阴分阳，迭用柔刚，故《易》六位而成章。"]],note:["三才各分两面，所以《易》以六画成卦；分阴分阳、迭用柔刚，所以六位而成章。"]},{id:"duan-04",label:"四、天地定位",showLabel:!0,sentences:[["天地定位，山泽通气，雷风相薄，水火不相射，八卦",{text:"相错",glossary:"g03"},"。"]],note:["天地各定其位，山泽气息相通，雷风相互激荡，水火不相侵害——这就是八卦错综相对的格局。"]},{id:"duan-05",label:"五、逆数知来",showLabel:!0,sentences:[["数往者顺，知来者逆，是故《易》",{text:"逆数",glossary:"g04"},"也。"]],note:["推算已往之事是顺，预知将来之事是逆，所以《易》是「逆数」——从来处推去处，以见未然。"]},{id:"duan-06",label:"六、八卦之用",showLabel:!0,sentences:[["雷以动之，风以散之，雨以润之，日以烜之，艮以止之，兑以",{text:"说",glossary:"g06"},"之，乾以君之，坤以藏之。"]],note:["雷用来鼓动，风用来吹散，雨用来滋润，日用来晒照，艮用来止住，兑用来悦人，乾用来统率，坤用来收藏。"]},{id:"duan-07",label:"七、帝出乎震",showLabel:!0,sentences:[["帝出乎震，齐乎巽，相见乎离，致役乎坤，说言乎兑，战乎乾，劳乎坎，成言乎艮。"]],note:["「帝出乎震」以下写万物在时间中的流转：从震出发，历巽、离、坤、兑、乾、坎，终于艮。"]},{id:"duan-08",label:"八、震巽位次",showLabel:!0,sentences:[["万物出乎震，震东方也。齐乎巽，巽东南也；齐也者，言万物之",{text:"絜齐",glossary:"g05"},"也。"]],note:["万物出于震，震是东方；齐乎巽，巽是东南——「齐」是说万物到此生长整齐。"]},{id:"duan-09",label:"九、离为南方",showLabel:!0,sentences:[["离也者，明也，万物皆相见，南方之卦也；圣人南面而听天下，向明而治，盖取诸此也。"]],note:["离是明，万物都在此相见，是南方之卦。圣人南面而听天下、向明而治，正是取象于此。"]},{id:"duan-10",label:"十、坤地兑秋",showLabel:!0,sentences:[["坤也者，地也，万物皆致养焉，故曰致役乎坤。兑，正秋也，万物之所说也，故曰说言乎兑。"]],note:["坤是地，万物都靠它致养，所以说「致役乎坤」；兑是正秋，万物在此欣悦，所以说「说言乎兑」。"]},{id:"duan-11",label:"十一、战乾劳坎",showLabel:!0,sentences:[["战乎乾，乾西北之卦也，言阴阳相薄也。坎者水也，正北方之卦也，劳卦也，万物之所归也，故曰劳乎坎。"]],note:["「战乎乾」，乾是西北之卦，说的是阴阳在此相迫；坎是水、是正北之卦，也是劳卦，万物于此归藏，所以说「劳乎坎」。"]},{id:"duan-12",label:"十二、艮成终始",showLabel:!0,sentences:[["艮，东北之卦也，万物之所成终而成始也，故曰成言乎艮。"]],note:["艮是东北之卦，万物于此成其终而又成其始，所以说「成言乎艮」。"]},{id:"duan-13",label:"十三、神妙万物",showLabel:!0,sentences:[["神也者，妙万物而为言者也。动万物者莫疾乎雷，挠万物者莫疾乎风，躁万物者莫乎火，说万物者莫说乎泽，润万物者莫润乎水，终万物始万物者莫盛乎艮。"]],note:["所谓「神」，是就其妙用万物而言：动万物没有比雷更快的，挠万物没有比风更快的，燥万物没有比火更快的，悦万物没有比泽更甚的，润万物没有比水更甚的，终始万物没有比艮更盛的。"]},{id:"duan-14",label:"十四、变化成物",showLabel:!0,sentences:[["故水火相逮，雷风不相悖，山泽通气，然后能变化，既成万物也。"]],note:["所以水火相济、雷风不相违、山泽气息相通，然后才能变化，从而成就万物。"]},{id:"duan-15",label:"十五、八卦之性",showLabel:!0,sentences:[["乾，健也；坤，顺也；震，动也；巽，入也；坎，陷也；离，",{text:"丽",glossary:"g07"},"也；艮，止也；兑，说也。"]],note:["乾是健，坤是顺，震是动，巽是入，坎是陷，离是丽，艮是止，兑是说——八个字把八卦的本性定了下来。"]},{id:"duan-16",label:"十六、八卦动物象",showLabel:!0,sentences:[["乾为马，坤为牛，震为龙，巽为鸡，坎为豕，离为雉，艮为狗，兑为羊。"]],note:["乾为马，坤为牛，震为龙，巽为鸡，坎为豕，离为雉，艮为狗，兑为羊。（以动物取象，各取其性情举止：马健行、牛顺载、龙动变、鸡知时、豕喜湿、雉文明、狗能守、羊性顺而悦。）"]},{id:"duan-17",label:"十七、八卦身体象",showLabel:!0,sentences:[["乾为首，坤为腹，震为足，巽为股，坎为耳，离为目，艮为手，兑为口。"]],note:["乾为首，坤为腹，震为足，巽为股，坎为耳，离为目，艮为手，兑为口。"]},{id:"duan-18",label:"十八、乾坤父母",showLabel:!0,sentences:[["乾，天也，故称乎父；坤，地也，故称乎母。震",{text:"一索",glossary:"g08"},"而得男，故谓之长男；巽",{text:"一索",glossary:"g08"},"而得女，故谓之长女。"]],note:["乾是天，所以称父；坤是地，所以称母。震一索而得男，所以谓之长男；巽一索而得女，所以谓之长女。"]},{id:"duan-19",label:"十九、六子次第",showLabel:!0,sentences:[["坎再索而得男，故谓之中男；离再索而得女，故谓之中女；艮三索而得男，故谓之少男；兑三索而得女，故谓之少女。"]],note:["坎再索而得男，所以谓之中男；离再索而得女，所以谓之中女；艮三索而得男，所以谓之少男；兑三索而得女，所以谓之少女。"]},{id:"duan-20",label:"二十、乾之象",showLabel:!0,sentences:[["乾为天，为圆，为君，为父，为玉，为金，为寒，为冰，为大赤，为良马，为老马，为瘠马，为驳马，为木果。"]],note:["乾为天、为圆、为君、为父、为玉、为金、为寒、为冰、为大赤、为良马、为老马、为瘠马、为驳马、为木果。（乾的取象最广：天道、尊长、金玉、寒冰色赤，到马之良、老、瘠、驳，皆是取其刚健之性；木果则取其结实。）"]},{id:"duan-21",label:"二十一、坤之象",showLabel:!0,sentences:[["坤为地，为母，为布，为釜，为吝啬，为均，为子母牛，为大舆，为文，为众，为柄，其于地也为黑。"]],note:["坤为地、为母、为布、为釜、为吝啬、为均、为子母牛、为大舆、为文、为众、为柄，在地则是黑色。"]},{id:"duan-22",label:"二十二、震之象",showLabel:!0,sentences:[["震为雷，为龙，为玄黄，为旉，为大途，为长子，为决躁，为苍筤竹，为萑苇；其于马也为善鸣，为馵足，为作足，为的颡；其于稼也为反生，其究为健，为蕃鲜。"]],note:["震为雷、为龙、为玄黄、为旉、为大途、为长子、为决躁、为苍筤竹、为萑苇；于马为善鸣、馵足、作足、的颡；于庄稼为反生；其究极为健，为蕃鲜。（旉是布散，决躁是决动而躁，苍筤是青色嫩竹；馵足是后左足白，作足是两足并举，的颡是额有白点；反生是苗生而根在上。）"]},{id:"duan-23",label:"二十三、巽之象",showLabel:!0,sentences:[["巽为木，为风，为长女，为绳直，为工，为白，为长，为高，为进退，为不果，为臭；其于人也为寡发，为广颡，为多白眼，为近利市三倍，其究为躁卦。"]],note:["巽为木、为风、为长女、为绳直、为工、为白、为长、为高、为进退、为不果、为臭；于人则为寡发、广颡、多白眼、近利市三倍；其究极为躁卦。（寡发、广颡、多白眼皆以形貌取象；进退、不果谓其柔而少定；近利市三倍，取其顺而能入。）"]},{id:"duan-24",label:"二十四、坎之象",showLabel:!0,sentences:[["坎为水，为沟渎，为隐伏，为矫輮，为弓轮；其于人也为加忧，为心病，为耳痛，为血卦，为赤；其于马也为美脊，为亟心，为下首，为薄蹄，为曳；其于舆也为多眚，为通，为月，为盗；其于木也为坚多心。"]],note:["坎为水、为沟渎、为隐伏、为矫輮、为弓轮；于人则为加忧、为心病、为耳痛、为血卦、为赤；于马则为美脊、为亟心、为下首、为薄蹄、为曳；于车则为多眚、为通、为月、为盗；于木则为坚而多心。（矫輮是使曲使直，亟心谓心坚，下首谓低头，薄蹄谓蹄薄；坎为陷为险，故其象多与忧、病、隐伏、险阻相关。）"]},{id:"duan-25",label:"二十五、离之象",showLabel:!0,sentences:[["离为火，为日，为电，为中女，为甲胄，为戈兵；其于人也为大腹，为乾卦，为鳖，为蟹，为蠃，为蚌，为龟；其于木也为科上槁。"]],note:["离为火、为日、为电、为中女、为甲胄、为戈兵；于人则为大腹、为乾卦、为鳖、为蟹、为蠃、为蚌、为龟；于木则为科上槁。（甲胄戈兵取其外刚，大腹谓中虚；蠃即螺。凡外坚中空之象，多归于离。）"]},{id:"duan-26",label:"二十六、艮之象",showLabel:!0,sentences:[["艮为山，为径路，为小石，为门阙，为果蓏，为阍寺，为指，为狗，为鼠，为黔喙之属；其于木也为坚多节。"]],note:["艮为山、为径路、为小石、为门阙、为果蓏、为阍寺、为指、为狗、为鼠、为黔喙之属；于木则为坚而多节。（阍寺是守门之人，黔喙是黑喙的走兽，果蓏是草木之实。凡止而不进之象，多归于艮。）"]},{id:"duan-27",label:"二十七、兑之象",showLabel:!0,sentences:[["兑为泽，为少女，为巫，为口舌，为毁折，为附决；其于地也为刚卤，为妾，为羊。"]],note:["兑为泽、为少女、为巫、为口舌、为毁折、为附决；于地则为刚卤、为妾、为羊。（刚卤是坚硬的盐碱地；巫以言说通神，口舌取其言；毁折、附决谓秋之肃杀，柔附于刚而致决。）"]}],s=[{id:"g01",term:"幽赞",pinyin:"yōu zàn",meaning:"在幽微处辅助、赞襄神明。放在作《易》的语境中，指对不可尽见的变化保持敬畏，并由此进入蓍筮与象数。"},{id:"g02",term:"三才",pinyin:"sān cái",meaning:"天、地、人。天道为阴阳，地道为柔刚，人道为仁义；三才各有两面，重之而成六画。"},{id:"g03",term:"相错",pinyin:"xiāng cuò",meaning:"彼此交错、相对配置。先天八卦以乾坤、山泽、雷风、水火等对待关系呈现结构。"},{id:"g04",term:"逆数",pinyin:"nì shǔ",meaning:"由已见之象推知未至之事。「数往者顺，知来者逆」说明《易》包含由现在观未来的推演方向。"},{id:"g05",term:"絜齐",pinyin:"jié qí",meaning:"整齐、齐一。「齐乎巽」写万物在生长过程中逐渐整饬、成形，而非静止排列。"},{id:"g06",term:"说",pinyin:"tuō",meaning:"在「兑以说之」「兑，说也」中通「悦」，指和悦、喜悦、使万物舒展。"},{id:"g07",term:"丽",pinyin:"lí",meaning:"附丽、依附。「离，丽也」不是单指美丽，而是事物有所附着，因依托而明。"},{id:"g08",term:"一索",pinyin:"yī suǒ",meaning:"第一次求取、交感。乾坤为父母，三次交感分别生出长、中、少三男三女，是八卦亲属象的生成说明。"},{id:"g09",term:"取象",pinyin:"qǔ xiàng",meaning:"从卦德、卦形、功能、关系或经验中取其相似之意。象例不是穷举，关键是会通当前情境中的那个意。"},{id:"g10",term:"先天",pinyin:"xiān tiān",meaning:"在本页主要指天地定位、山泽通气等对待结构，偏重空间关系与阴阳相对。"},{id:"g11",term:"后天",pinyin:"hòu tiān",meaning:"在本页主要指帝出乎震、成言乎艮的流行次序，偏重时间、方位与万物生长收藏。"},{id:"g12",term:"成终成始",pinyin:"chéng zhōng chéng shǐ",meaning:"既完成一个周期，又开启下一个周期。「艮」处于后天方位的终始交界，提示结束与开始相接。"}];return(p,e)=>{const r=a("DaoReadingPrelude"),d=a("DaoTextReading"),u=a("DaoKeywordCards");return g(),c("div",null,[e[0]||(e[0]=n("h1",{id:"说卦传",tabindex:"-1"},[l("说卦传 "),n("a",{class:"header-anchor",href:"#说卦传","aria-label":'Permalink to "说卦传"'},"​")],-1)),i(r,{title:"先会其意，再进入万象",summary:"《说卦传》是十翼中专门展开八卦系统的一篇：它说明圣人如何作《易》，天地人三才如何成为六画，八卦如何对应自然、身体、亲属、动物与器物，也呈现先天的对待和后天的流行。它不是一张必须死背的对应表，而是一套从意入象、由象观变的阅读方法。",points:[{label:"先明根",text:"先读圣人作易的步骤，以及阴阳、柔刚、仁义的三才结构。"},{label:"再识象",text:"掌握八卦最核心的卦德：健、顺、动、入、陷、丽、止、说。"},{label:"后会通",text:"再看先天对待、后天流行和广取象，不把象例误当成穷尽。"}],hint:"取象的关键不是遇到任何事都机械查表，而是先问：此刻我取的是哪一种意？同一事物因所取之意不同，可能显出不同的卦象。"}),e[1]||(e[1]=t("",12)),i(d,{colophon:"幽赞神明 · 三才六画 · 先后天方位 · 广取象",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"说卦传原文",sections:o,glossary:s}),e[2]||(e[2]=n("blockquote",null,[n("p",null,"注：本页据通行本整理。「艮为手」与后文「艮为指」等文字，在历代传本、注疏和后世易学中有不同讨论；「离为中女」按上下文及通行本校正。取象解释也不等同于经文逐项给出唯一推导。")],-1)),e[3]||(e[3]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[l("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(u,{items:[{term:"幽赞",pinyin:["yōu","zàn"],meaning:"在幽微处辅助、赞襄神明。放在作《易》的语境中，指对不可尽见的变化保持敬畏，并由此进入蓍筮与象数。"},{term:"三才",pinyin:["sān","cái"],meaning:"天、地、人。天道为阴阳，地道为柔刚，人道为仁义；三才各有两面，重之而成六画。"},{term:"相错",pinyin:["xiāng","cuò"],meaning:"彼此交错、相对配置。先天八卦以乾坤、山泽、雷风、水火等对待关系呈现结构。"},{term:"逆数",pinyin:["nì","shǔ"],meaning:"由已见之象推知未至之事。「数往者顺，知来者逆」说明《易》包含由现在观未来的推演方向。"},{term:"絜齐",pinyin:["jié","qí"],meaning:"整齐、齐一。「齐乎巽」写万物在生长过程中逐渐整饬、成形，而非静止排列。"},{term:"说",pinyin:["tuō"],meaning:"在「兑以说之」「兑，说也」中通「悦」，指和悦、喜悦、使万物舒展。"},{term:"丽",pinyin:["lí"],meaning:"附丽、依附。「离，丽也」不是单指美丽，而是事物有所附着，因依托而明。"},{term:"一索",pinyin:["yī","suǒ"],meaning:"第一次求取、交感。乾坤为父母，三次交感分别生出长、中、少三男三女，是八卦亲属象的生成说明。"},{term:"取象",pinyin:["qǔ","xiàng"],meaning:"从卦德、卦形、功能、关系或经验中取其相似之意。象例不是穷举，关键是会通当前情境中的那个意。"},{term:"先天",pinyin:["xiān","tiān"],meaning:"在本页主要指天地定位、山泽通气等对待结构，偏重空间关系与阴阳相对。"},{term:"后天",pinyin:["hòu","tiān"],meaning:"在本页主要指帝出乎震、成言乎艮的流行次序，偏重时间、方位与万物生长收藏。"},{term:"成终成始",pinyin:["chéng","zhōng","chéng","shǐ"],meaning:"既完成一个周期，又开启下一个周期。「艮」处于后天方位的终始交界，提示结束与开始相接。"}]}),e[4]||(e[4]=t("",21))])}}});export{x as __pageData,q as default};
